<?php
namespace App\Http\Controllers\Website;use App\Http\Controllers\Controller;use App\Http\Requests\Website\SaveContentRequest;use App\Models\{LandingAchievement,LandingFacility,LandingNews,LandingProgram,LandingTestimonial};use App\Services\Website\MediaService;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
class WebsiteContentController extends Controller {private function model(string $type):string{return match($type){'program'=>LandingProgram::class,'facility'=>LandingFacility::class,'achievement'=>LandingAchievement::class,'news'=>LandingNews::class,'testimonial'=>LandingTestimonial::class,default=>abort(404)};}public function index(string $type){$class=$this->model($type);return view('website.admin.content-index',['type'=>$type,'items'=>$class::latest()->paginate(15)]);}public function create(string $type){$this->model($type);return view('website.admin.content-form',['type'=>$type,'item'=>null]);}public function store(SaveContentRequest $r,string $type,MediaService $media){$class=$this->model($type);$data=$this->data($r,$type,$media);$class::create($data);return redirect()->route('website.content.index',$type)->with('status','Konten berhasil ditambahkan.');}public function edit(string $type,int $id){$class=$this->model($type);return view('website.admin.content-form',['type'=>$type,'item'=>$class::findOrFail($id)]);}public function update(SaveContentRequest $r,string $type,int $id,MediaService $media){$class=$this->model($type);$item=$class::findOrFail($id);$item->update($this->data($r,$type,$media,$item));return back()->with('status','Konten berhasil diperbarui.');}public function destroy(string $type,int $id,MediaService $media){$class=$this->model($type);$item=$class::findOrFail($id);$media->delete($item->image??$item->featured_image??$item->photo??null);$item->delete();return back()->with('status','Konten berhasil dihapus.');}private function data(SaveContentRequest $r,string $type,MediaService $media,?Model $item=null):array{$allowed=match($type){'program'=>['title','slug','icon','summary','description','sort_order','is_active','featured'],'facility'=>['name','slug','description','icon','sort_order','is_active'],'achievement'=>['title','category','description','year','date','sort_order','is_active','featured'],'news'=>['title','slug','category','excerpt','content','published_at','status','featured'],'testimonial'=>['name','relation','content','rating','sort_order','is_active']};$input=$r->validated();if($type==='testimonial')$input['content']=$r->input('description');$d=collect($input)->only($allowed)->all();$d['is_active']=$r->boolean('is_active');$d['featured']=$r->boolean('featured');if(in_array($type,['program','facility','news'])){$base=$d['title']??$d['name']??'';$d['slug']=$d['slug']?:Str::slug($base).'-'.Str::lower(Str::random(5));}if($type==='news'){$d['author_id']=$r->user()->id;$field='featured_image';}elseif($type==='testimonial')$field='photo';else $field='image';$path=$media->replace($r->file('image'),$item?->{$field},$type);unset($d['image']);$d[$field]=$path;return $d;}}
